#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int maxn = 2e5;
int n, h[maxn + 3], t[maxn + 3], in[maxn + 3], out[maxn + 3];
vector<int> G[maxn + 3];
bool vis[maxn + 3];
ll ans, f[maxn + 3], g[maxn + 3], a[maxn + 3];

void dfs(int u, int fa = 0) {
	vis[u] = true;
	for (int i = 0, v; i < G[u].size(); i++) {
		if ((v = G[u][i]) == fa) continue;
		dfs(v, u);
	}
	int s = 0;
	ll cur = 0;
	for (int i = 0, v; i < G[u].size(); i++) {
		if ((v = G[u][i]) == fa) continue;
		cur += g[v], a[++s] = f[v] - g[v];
	}
	sort(a + 1, a + s + 1);
	reverse(a + 1, a + s + 1);
	for (int i = 0; i <= s; i++) {
		cur += a[i];
		if (fa) {
			f[u] = max(f[u], 1ll * min(in[u] + 1 + s - i, out[u] + i) * t[u] + cur);
			g[u] = max(g[u], 1ll * min(in[u] + s - i, out[u] + 1 + i) * t[u] + cur);
		} else {
			f[u] = max(f[u], 1ll * min(in[u] + s - i, out[u] + i) * t[u] + cur);
		}
	}
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) scanf("%d", &t[i]);
	for (int i = 1; i <= n; i++) scanf("%d", &h[i]);
	for (int i = 1, u, v; i < n; i++) {
		scanf("%d %d", &u, &v);
		ans += t[u] + t[v];
		if (h[u] == h[v]) {
			G[u].push_back(v), G[v].push_back(u);
		} else {
			if (h[u] > h[v]) swap(u, v);
			in[u]++, out[v]++;
		}
	}
	for (int i = 1; i <= n; i++) if (!vis[i]) {
		dfs(i), ans -= f[i];
	}
	printf("%lld\n", ans);
	return 0;
}

